add_action( 'woocommerce_payment_complete', 'perfectpixel_add_products_after_purchase', 5 );
add_action( 'woocommerce_order_status_processing', 'perfectpixel_add_products_after_purchase', 5 );

function perfectpixel_add_products_after_purchase( $order_id ) {
	$order   = wc_get_order( $order_id );
	$trigger = (int) '{{bundle_trigger_product_id}}';
	if ( ! $order || ! $trigger || $order->get_meta( '_perfectpixel_bundle_added' ) ) {
		return;
	}
	$found = false;
	foreach ( $order->get_items() as $item ) {
		if ( (int) $item->get_product_id() === $trigger ) {
			$found = true;
			break;
		}
	}
	if ( ! $found ) {
		return;
	}
	foreach ( wp_parse_id_list( '{{bundle_added_product_ids}}' ) as $product_id ) {
		$product = wc_get_product( $product_id );
		if ( $product ) {
			$order->add_product( $product, 1, array( 'subtotal' => 0, 'total' => 0 ) );
		}
	}
	$order->update_meta_data( '_perfectpixel_bundle_added', 1 );
	$order->calculate_totals( false );
	$order->save();
}
